args <- commandArgs(trailingOnly = TRUE)
library(weather.client, lib.loc = args[1L], character.only = FALSE)
ns <- asNamespace('weather.client')
internal <- function(name) get(paste0('.crucible_', name), ns)
codec <- internal('codec'); epoch <- internal('epoch'); epoch_text <- internal('epoch_text')
time_decode <- internal('time_decode'); time_encode <- internal('time_encode')
check <- function(value, label) if (!isTRUE(value)) stop(label, call. = FALSE)
rejects <- function(expression, class = 'error') { result <- tryCatch({ force(expression); NULL }, error = identity); if (is.null(result) || !inherits(result, class)) stop('Expected ', class, ', got ', paste(result, collapse=' ')); result }
response <- function(status = 200L, body = '{}', headers = list()) list(status = status, body = if (is.raw(body)) body else charToRaw(body), headers = headers)
fake <- function(handler) {
  state <- new.env(); state$requests <- list()
  state$send <- function(request, read_body, scope) { state$requests[[length(state$requests)+1L]] <- request; handler(length(state$requests), request) }
  state
}
sdk <- function(fake, ...) Client(client_config(endpoint = 'https://example.invalid', transport = fake$send, base_delay = 0, ...))

check(json_encode(json_parse('{"a":9223372036854775807,"b":1.000000000000000000001,"c":{},"d":[]}')) == '{"a":9223372036854775807,"b":1.000000000000000000001,"c":{},"d":[]}', 'Exact JSON and empty container identity')
for (text in c('NaN', '[1,]', '01', 'true false', '"\\udc00"', '"\\ud800"', '"\\ud800x"', '"\\ud800\\ud800"', '"\\u0000"')) rejects(json_parse(text))
check(json_parse('"\\ud83d\\ude00"') == intToUtf8(128512L), 'Valid UTF-16 surrogate pair')
rejects(json_encode(Inf)); rejects(long('9223372036854775808')); rejects(long('-9223372036854775809')); rejects(long('1.1')); rejects(long(2^63))
for (seconds in c('-9223372036854775808','-1','0','9223372036854775807')) {
  value <- timestamp(seconds, 999999999L); copy <- epoch(epoch_text(value)); check(identical(value, copy), 'Exact epoch extremes')
}
check(time_encode(epoch('-0.000000001'),'date-time') == '1969-12-31T23:59:59.999999999Z','Negative epoch')
check(time_encode(time_decode('1582-10-10T00:00:00Z','date-time'),'date-time') == '1582-10-10T00:00:00Z','Gregorian date')
check(time_encode(time_decode('2026-10-01T01:30:00+01:30','date-time'),'date-time') == '2026-10-01T00:00:00Z','Timezone offset')
for (text in c('2026-02-30T00:00:00Z','1500-02-29T00:00:00Z','2026-01-01T24:00:00Z')) rejects(time_decode(text,'date-time'))
rejects(epoch('0.0000000001')); rejects(time_decode('Fri, 01 Jan 1970 00:00:00 GMT','http-date'))
input <- CreateCityInput(name = 'R', location = Location('future', json_parse('{"long":9223372036854775807}')))
wire <- codec(input, 'example.weather#CreateCityInput', TRUE)
check(!'clientToken' %in% names(wire) && as.character(wire$location$future$long) == '9223372036854775807','Native wire')
copy <- codec(wire,'example.weather#CreateCityInput'); check(inherits(copy$location,'Location') && copy$name == 'R','Native model round trip')
check(json_encode(codec(CreateCityInput(name = NULL),'example.weather#CreateCityInput',TRUE)) == '{"name":null}','Unset vs null')
rejects(codec(input,'example.weather#GetCityInput',TRUE))
decoded <- codec(json_parse('{"document":null}'),'example.weather#ExactValues')
check(is.null(decoded$document) && as.character(decoded$default_long)=='9223372036854775807' && inherits(decoded$optional_long,'crucible_unset'),'Required document null and exact default')
rejects(codec(json_object(),'example.weather#ExactValues'))
rejects(codec(json_parse('{"document":null,"defaultLong":null}'),'example.weather#ExactValues'))
check(is.null(codec(json_parse('{"document":null,"optionalLong":null}'),'example.weather#ExactValues')$optional_long),'Explicit optional null')
recursive <- ExactValues(document=NULL,default_long=long('1'),next_value=decoded)
check(identical(codec(codec(recursive,'example.weather#ExactValues',TRUE),'example.weather#ExactValues'),recursive),'Recursive native model')
rejects(codec(setNames(list(NULL,NULL),c('clear','clear')),'example.weather#Forecast',TRUE))
check(json_encode(codec(json_object(future=NULL),'example.weather#Forecast',TRUE))=='{"future":null}','Open enum map keys and document null')
rejects(internal('request')(list(url='https://example.invalid',method="GET\r\nx:y",headers=list(),body=NULL)))
rejects(client_config(headers=list(x="y\r\nz")))

for (row in jsonlite::fromJSON(Sys.getenv('HEADER_CASES'), simplifyVector = FALSE)) {
  description <- list(target='example.weather#TagList')
  schema <- get('.crucible_schema',ns)
  targets <- names(Filter(function(s) identical(s$kind,'list') && identical(schema$shapes[[s$member$target]]$kind,'string'), schema$shapes))
  check(length(targets)>0,'Header list fixture target'); description$target <- targets[1L]
  check(identical(internal('header')(description,row$wire),row$values),'Header shared fixture')
  check(identical(internal('header')(description,internal('bound')(row$values)),row$values),'Header round trip')
}
for (row in jsonlite::fromJSON(Sys.getenv('RETRY_CASES'), simplifyVector = FALSE)) {
  test <- fake(function(attempt, request) response(if (attempt <= row$failures) row$status else 200, if (is.null(row$error)) '{}' else json_encode(json_object(`__type`=row$error)), list('x-amzn-errortype'='Throttled')))
  client <- sdk(test,max_attempts=row$maxAttempts)
  success <- tryCatch({ if (row$safe) client$retry_safe() else client$retry_unsafe(); TRUE }, crucible_service_error=function(e) FALSE)
  check(identical(success,row$success) && length(test$requests)==row$attempts,paste('Shared retry',row$name)); client$close()
}
test <- fake(function(attempt,request) {
  check(grepl('a%2Fb%20%2A%3F%23%C3%A9',request$url,fixed=TRUE),'Label encoding')
  check(grepl('at=2026-10-01T00%3A00%3A00Z',request$url,fixed=TRUE),'Timestamp query')
  response(body='{"city":{"id":"x","name":"n"}}',headers=list('x-request-id'='bound'))
})
check(sdk(test)$get_city(GetCityInput(city_id='a/b *?#é',at=time_decode('2026-10-01T00:00:00Z','date-time')))$request_id=='bound','Bound response header')
count <- 0L
test <- fake(function(attempt,request) {
  check(request$headers$authorization==paste('Bearer',attempt),'Refreshed token')
  check(request$headers[['x-amz-content-sha256']]==as.character(openssl::sha256(request$body)),'Final digest')
  response(if(attempt==1)503 else 201,if(attempt==1)'{"__type":"Future"}' else '{"city":{"id":"x","name":"n"}}')
})
client <- sdk(test,token=function(){count<<-count+1L;as.character(count)},middleware=list(function(request){request$body<-c(request$body,charToRaw(' '));request}))
client$create_city(input)
check(identical(test$requests[[1]]$body,test$requests[[2]]$body) && inherits(input$client_token,'crucible_unset'),'Stable body and caller ownership')
test <- fake(function(attempt,request) response(429,'{"__type":"ThrottlingError","message":42}',list('x-request-id'='header')))
error <- rejects(sdk(test,max_attempts=2)$ping(),'crucible_service_error')
check(error$metadata$status==429 && error$metadata$throttling && error$metadata$request_id=='header' && length(test$requests)==2,'Malformed typed error preserves metadata')
test <- fake(function(attempt,request) response(404,'{"messageExtra":"wrong","requestIdentifier":"wrong"}'))
error <- rejects(sdk(test,max_attempts=1)$ping(),'crucible_service_error')
check(error$metadata$message=='HTTP 404' && is.null(error$metadata$request_id),'Error metadata uses exact member names')
test <- fake(function(attempt,request) response(body='{bad'))
rejects(sdk(test)$get_city(GetCityInput(city_id='x'))); check(length(test$requests)==1,'Malformed success does not retry')
test <- fake(function(attempt,request) response(body='{"cities":[],"nextToken":"same"}'))
pages <- sdk(test)$list_cities_pages(ListCitiesInput()); check(length(test$requests)==0,'Lazy paginator')
pages(); pages(); rejects(pages()); check(length(test$requests)==2,'Pagination cycle')
test <- fake(function(attempt,request) response(503,headers=list('retry-after'='2147484')))
rejects(sdk(test,timeout=.05)$retry_safe(),'crucible_deadline'); check(length(test$requests)==1,'Whole-call retry deadline')
cancel <- cancellation_token(); cancel$cancel(); test <- fake(function(attempt,request) response())
rejects(sdk(test)$ping(cancellation=cancel),'crucible_cancelled'); check(length(test$requests)==0,'Pre-cancelled call')
polls <- 0L; cancel <- cancellation_token(function(){polls<<-polls+1L;polls==1L})
rejects(cancel$check(),'crucible_cancelled'); rejects(cancel$check(),'crucible_cancelled'); check(polls==1,'Latched cancellation')

if (Sys.getenv('R_OFFLINE_TESTS') == '1') { cat('R exact codecs, shared fixtures, and fake transport qualification passed\n'); quit(status=0) }

client <- Client(client_config(endpoint=Sys.getenv('WEATHER_URL'),token=function()'weather-token'))
city <- client$create_city(CreateCityInput(name='R city'))$city
check(client$get_city(GetCityInput(city_id=city$id))$city$name=='R city','Native create/read')
photo <- as.raw(c(0,128,255)); client$put_city_photo(PutCityPhotoInput(city_id=city$id,photo=photo))
check(identical(client$get_city_photo(GetCityPhotoInput(city_id=city$id))$photo,photo),'Native raw payload')
pages <- client$list_cities_pages(ListCitiesInput(max_results=1)); check(!is.null(pages()),'Native pagination')
rejects(client$create_city(CreateCityInput(name='R city')),'ConflictError'); client$ping(); client$close()
fixture <- paste0(Sys.getenv('FIXTURE_URL'),'/native/')
client <- Client(client_config(endpoint=paste0(fixture,'partial'),base_delay=0)); check(rawToChar(client$get_city_photo(GetCityPhotoInput(city_id='x'))$photo)=='complete','Partial response retry'); client$close()
client <- Client(client_config(endpoint=paste0(fixture,'bad-length'),base_delay=0)); check(rawToChar(client$get_city_photo(GetCityPhotoInput(city_id='x'))$photo)=='complete','Malformed content length retry'); client$close()
client <- Client(client_config(endpoint=paste0(fixture,'empty-header'),headers=list('x-empty'=''))); client$ping(); client$close()
client <- Client(client_config(endpoint=paste0(fixture,'not-modified'),max_attempts=1)); check(rejects(client$get_city(GetCityInput(city_id='x')),'crucible_service_error')$metadata$status==304,'304 keeps status'); client$close()
client <- Client(client_config(endpoint=paste0(fixture,'stall'),timeout=.15)); started<-proc.time()[['elapsed']]; rejects(client$get_city(GetCityInput(city_id='x')),'crucible_deadline'); check(proc.time()[['elapsed']]-started<1.5,'Stalled deadline'); client$close()
client <- Client(client_config(endpoint=paste0(fixture,'stall'),timeout=5)); started<-proc.time()[['elapsed']]; cancel<-cancellation_token(function()proc.time()[['elapsed']]-started>=.1); rejects(client$get_city(GetCityInput(city_id='x'),cancellation=cancel),'crucible_cancelled'); check(proc.time()[['elapsed']]-started<1.5,'Stalled cancellation'); client$close()
client <- Client(client_config(endpoint=paste0(fixture,'discard'),timeout=.5)); client$ping(); client$close()
client <- Client(client_config(endpoint=paste0(fixture,'redirect'),max_attempts=1)); check(rejects(client$ping(),'crucible_service_error')$metadata$status==302,'Redirect refusal'); client$close()
count <- 0L; client <- Client(client_config(endpoint=paste0(fixture,'echo'),base_delay=0,token=function(){count<<-count+1L;as.character(count)})); client$create_city(CreateCityInput(name='x')); check(count==2,'Native refreshed retry token'); client$close()
count <- 0L; client <- Client(client_config(endpoint=paste0(fixture,'cache'),token=function(){count<<-count+1L;as.character(count)})); check(client$get_city(GetCityInput(city_id='c'))$city$name=='Bearer 1','First token'); check(client$get_city(GetCityInput(city_id='c'))$city$name=='Bearer 2','No cached credential response'); client$close()
cat('R exact codecs, shared fixtures, native models, and HTTP qualification passed\n')
